import React, { useState, useRef, useEffect, useCallback } from 'react';
import { attendanceAPI } from './api_service';

const COLORS = {
  primary: '#4F46E5',
  success: '#10B981',
  danger: '#EF4444',
  warning: '#F59E0B',
  textMain: '#1E293B',
  textMuted: '#64748B',
  border: '#E2E8F0',
  background: '#F8FAFC',
  surface: '#FFFFFF'
};

const CameraRecognition = ({ addNotification }) => {
  // ==================== REFS ====================
  const videoRef = useRef(null);
  const streamRef = useRef(null);
  const intervalRef = useRef(null);
  const isProcessingRef = useRef(false);

  // ==================== STATE ====================
  const [cameraActive, setCameraActive] = useState(false);
  const [autoMode, setAutoMode] = useState(false);
  const [detecting10s, setDetecting10s] = useState(false);
  const [detectionProgress, setDetectionProgress] = useState(0);
  const [capturedPhoto, setCapturedPhoto] = useState(null);
  const [matchResult, setMatchResult] = useState(null);
  const [error, setError] = useState(null);
  const [videoReady, setVideoReady] = useState(false);
  const [frameCount, setFrameCount] = useState(0);

  // ==================== DÉMARRER LA CAMÉRA ====================
  const startCamera = useCallback(async () => {
    try {
      setError(null);

      // Nettoyer ancien stream
      if (streamRef.current) {
        streamRef.current.getTracks().forEach(track => track.stop());
      }

      const constraints = {
        video: {
          facingMode: 'user',
          width: { ideal: 1280 },
          height: { ideal: 720 },
          aspectRatio: { ideal: 16 / 9 }
        },
        audio: false
      };

      const stream = await navigator.mediaDevices.getUserMedia(constraints);
      streamRef.current = stream;

      if (videoRef.current) {
        videoRef.current.srcObject = stream;
      }

      setCameraActive(true);
      setVideoReady(true);
      addNotification('✅ Caméra activée avec succès', 'success');

    } catch (err) {
      console.error('Erreur caméra:', err);
      let message = 'Impossible d\'accéder à la caméra';

      if (err.name === 'NotAllowedError') message = 'Permission caméra refusée';
      else if (err.name === 'NotFoundError') message = 'Aucune caméra détectée';
      else if (err.name === 'NotReadableError') message = 'Caméra déjà utilisée par une autre application';

      setError(message);
      addNotification(`❌ ${message}`, 'error');
    }
  }, [addNotification]);

  // ==================== ARRÊTER LA CAMÉRA ====================
  const stopCamera = useCallback(() => {
    if (intervalRef.current) {
      clearInterval(intervalRef.current);
      intervalRef.current = null;
    }

    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
      streamRef.current = null;
    }

    if (videoRef.current) {
      videoRef.current.srcObject = null;
    }

    setCameraActive(false);
    setVideoReady(false);
    setAutoMode(false);
    setDetecting10s(false);
    setDetectionProgress(0);
    setFrameCount(0);
    setCapturedPhoto(null);
    setMatchResult(null);
    setError(null);
  }, []);

  // Nettoyage au démontage du composant
  useEffect(() => {
    return () => stopCamera();
  }, [stopCamera]);

  // ==================== TRAITER UNE FRAME ====================
  const processFrame = useCallback(async () => {
    if (!videoRef.current || isProcessingRef.current) return;

    isProcessingRef.current = true;
    setFrameCount(prev => prev + 1);

    try {
      const canvas = document.createElement('canvas');
      canvas.width = videoRef.current.videoWidth || 1280;
      canvas.height = videoRef.current.videoHeight || 720;

      const ctx = canvas.getContext('2d');
      ctx.drawImage(videoRef.current, 0, 0);

      const imageBase64 = canvas.toDataURL('image/jpeg', 0.85);

      const response = await attendanceAPI.recognize(imageBase64);
      const data = response?.data;

      if (data?.success && data.student && data.confidence > 0.35) {
        const finalPhoto = canvas.toDataURL('image/jpeg', 0.92);

        setCapturedPhoto(finalPhoto);
        setMatchResult({
          success: true,
          name: data.student,
          email: data.email || 'N/A',
          confidence: (data.confidence * 100).toFixed(1),
          attendanceId: data.attendance_id || 'N/A',
          timestamp: new Date().toLocaleTimeString('fr-FR')
        });

        addNotification(`✅ ${data.student} détecté avec succès !`, 'success');

        // Pause temporaire après détection en mode auto
        if (autoMode) {
          setAutoMode(false);
          setTimeout(() => setAutoMode(true), 4000);
        }
        if (detecting10s) {
          setDetecting10s(false);
        }
      }
    } catch (err) {
      console.warn('⚠️ Erreur lors de la reconnaissance:', err.message);
    } finally {
      isProcessingRef.current = false;
    }
  }, [addNotification, autoMode, detecting10s]);

  // ==================== MODE AUTO CONTINU ====================
  useEffect(() => {
    if (!autoMode || !cameraActive) {
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
        intervalRef.current = null;
      }
      return;
    }

    console.log('▶️ Mode Auto Continu activé (500ms)');
    intervalRef.current = setInterval(processFrame, 500);

    return () => {
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
        intervalRef.current = null;
      }
    };
  }, [autoMode, cameraActive, processFrame]);

  // ==================== DÉTECTION PENDANT 10 SECONDES ====================
  const startDetection10s = () => {
    if (!cameraActive || detecting10s) return;

    setDetecting10s(true);
    setDetectionProgress(0);
    setMatchResult(null);
    setError(null);

    const duration = 10000;
    const startTime = Date.now();

    intervalRef.current = setInterval(processFrame, 500);

    // Arrêt après 10 secondes
    setTimeout(() => {
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
        intervalRef.current = null;
      }
      setDetecting10s(false);
      setDetectionProgress(100);

      if (!matchResult) {
        setError('Aucun visage reconnu pendant les 10 secondes.');
      }
    }, duration);

    // Mise à jour de la progression
    const progressInterval = setInterval(() => {
      const elapsed = Date.now() - startTime;
      const progress = Math.min(100, (elapsed / duration) * 100);
      setDetectionProgress(progress);

      if (progress >= 100) clearInterval(progressInterval);
    }, 100);
  };

  // ==================== CAPTURE UNIQUE ====================
  const captureOnce = () => {
    processFrame();
  };

  // ==================== RÉINITIALISER ====================
  const resetDetection = () => {
    setMatchResult(null);
    setCapturedPhoto(null);
    setError(null);
    setDetectionProgress(0);
  };

  // ==================== RENDU ====================
  return (
    <div style={styles.container}>
      <div style={styles.header}>
        <h1 style={styles.title}>👤 Reconnaissance Faciale</h1>
        <p style={styles.subtitle}>
          {cameraActive 
            ? "Positionnez votre visage face à la caméra" 
            : "Cliquez sur 'Allumer caméra' pour commencer"}
        </p>
      </div>

      {/* Caméra */}
      {cameraActive ? (
        <div style={styles.videoSection}>
          <div style={styles.videoContainer}>
            <video
              ref={videoRef}
              autoPlay
              playsInline
              muted
              style={styles.video}
            />
            <div style={{
              ...styles.statusBadge,
              backgroundColor: autoMode || detecting10s ? '#EF4444' : '#10B981'
            }}>
              {autoMode ? '🔄 AUTO SCANNING' : detecting10s ? '🔍 DÉTECTION 10s' : '✅ CAMÉRA PRÊTE'}
            </div>
          </div>

          {(autoMode || detecting10s) && (
            <div style={styles.progressBar}>
              <div style={{ ...styles.progressFill, width: `${detectionProgress}%` }} />
            </div>
          )}
        </div>
      ) : (
        <div style={styles.cameraOffBox}>
          <p style={styles.cameraOffText}>📹 Caméra désactivée</p>
          <p style={styles.cameraOffSubtext}>Cliquez sur le bouton ci-dessous pour activer</p>
        </div>
      )}

      {/* Boutons d'action */}
      <div style={styles.actions}>
        {!cameraActive ? (
          <button onClick={startCamera} style={{ ...styles.btn, backgroundColor: COLORS.success }}>
            📹 Allumer Caméra
          </button>
        ) : (
          <>
            <button 
              onClick={captureOnce}
              disabled={autoMode || detecting10s}
              style={{ ...styles.btn, backgroundColor: COLORS.primary }}
            >
              📸 Capture Unique
            </button>

            <button 
              onClick={startDetection10s}
              disabled={autoMode || detecting10s}
              style={{ ...styles.btn, backgroundColor: COLORS.warning }}
            >
              🔍 Détection 10 secondes
            </button>

            <button 
              onClick={() => setAutoMode(!autoMode)}
              style={{ 
                ...styles.btn, 
                backgroundColor: autoMode ? COLORS.danger : '#8B5CF6' 
              }}
            >
              {autoMode ? '⏸️ Arrêter Auto' : '▶️ Mode Auto Continu'}
            </button>

            <button 
              onClick={stopCamera} 
              style={{ ...styles.btn, backgroundColor: COLORS.danger }}
            >
              🛑 Fermer Caméra
            </button>
          </>
        )}
      </div>

      {error && <div style={styles.errorBox}>{error}</div>}

      {/* Résultat */}
      {matchResult && (
        <div style={styles.resultSection}>
          <h2 style={styles.resultTitle}>✅ {matchResult.name} détecté !</h2>

          {capturedPhoto && (
            <div style={styles.imageContainer}>
              <img src={capturedPhoto} alt="Photo capturée" style={styles.capturedImage} />
            </div>
          )}

          <div style={styles.infoBox}>
            <div style={styles.infoRow}><span style={styles.infoLabel}>Nom :</span> <span>{matchResult.name}</span></div>
            <div style={styles.infoRow}><span style={styles.infoLabel}>Email :</span> <span>{matchResult.email}</span></div>
            <div style={styles.infoRow}><span style={styles.infoLabel}>Confiance :</span> <span style={{ color: COLORS.success, fontWeight: 'bold' }}>{matchResult.confidence}%</span></div>
            <div style={styles.infoRow}><span style={styles.infoLabel}>ID Présence :</span> <span>{matchResult.attendanceId}</span></div>
            <div style={styles.infoRow}><span style={styles.infoLabel}>Heure :</span> <span>{matchResult.timestamp}</span></div>
          </div>

          <button onClick={resetDetection} style={{ ...styles.btn, backgroundColor: COLORS.primary, marginTop: 20 }}>
            🔄 Nouvelle Détection
          </button>
        </div>
      )}
    </div>
  );
};

